(()=>{
 const root=document.documentElement;
 root.dataset.pageReady='pending';
 let shown=false;
 function reveal(reason){
  if(shown)return;shown=true;clearTimeout(deadline);
  root.dataset.fontLoad=reason;
  requestAnimationFrame(()=>requestAnimationFrame(()=>{root.dataset.pageReady='ready';}));
 }
 const deadline=setTimeout(()=>reveal('timeout'),2200);
 const dom=new Promise(resolve=>document.addEventListener('DOMContentLoaded',resolve,{once:true}));
 const fonts=document.fonts?Promise.all([
  ...[400,500,600,700].map(weight=>document.fonts.load(weight+' 16px "Pretendard"','MR.DEVELLO 미스터디벨로'))
 ]):Promise.resolve();
 Promise.all([dom,fonts]).then(()=>reveal('loaded'),()=>dom.then(()=>reveal('error')));
 addEventListener('pagereveal',event=>{
  if(!event.viewTransition)return;
  const cached=document.fonts&&[400,500,600,700].every(weight=>document.fonts.check(weight+' 16px "Pretendard"','MR.DEVELLO 미스터디벨로'));
  if(!cached||matchMedia('(prefers-reduced-motion:reduce)').matches){event.viewTransition.skipTransition();return;}
  shown=true;clearTimeout(deadline);root.dataset.fontLoad='loaded';
  root.dataset.pageNative='true';root.dataset.pageReady='ready';
 });
 addEventListener('pageshow',event=>{
  if(event.persisted){shown=true;clearTimeout(deadline);root.dataset.pageRestored='true';root.dataset.pageReady='ready';}
 });
})();
